const gen = [];
families.forEach(([fam, variants, unit, price]) => {
  variants.forEach(v => {
    n++;
    const stock = 20 + ((n * 37) % 300);
    gen.push({
      id: 'g' + n, name: fam + ' ' + v, sku: 'GEN-' + String(1000 + n), barcode: '46055500' + String(10000 + n),
      unit, price, stock, min: n % 4 === 0 ? Math.round(stock * 0.3) : 0, expired: n % 9 === 0 ? 3 : 0
    });
  });
});

